import{_ as d,o as a,c as n,a2 as e}from"./chunks/framework.CnJ-JtFX.js";const m=JSON.parse('{"title":"产品对照矩阵与选型决策","description":"","frontmatter":{},"headers":[],"relativePath":"appendix/comparison.md","filePath":"appendix/comparison.md","lastUpdated":1792683644000}'),s={name:"appendix/comparison.md"};function i(r,t,l,o,p,c){return a(),n("div",null,[...t[0]||(t[0]=[e(`<h1 id="产品对照矩阵与选型决策" tabindex="-1">产品对照矩阵与选型决策 <a class="header-anchor" href="#产品对照矩阵与选型决策" aria-label="Permalink to &quot;产品对照矩阵与选型决策&quot;">​</a></h1><p>本页是第 14 章的配套附录，也是全套教程的选型速查。矩阵只描述「能力形态与代价」，不做功能多少的排名。</p><h2 id="一张总表" tabindex="-1">一张总表 <a class="header-anchor" href="#一张总表" aria-label="Permalink to &quot;一张总表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>amis</th><th>Formily</th><th>lowcode-engine</th><th>tmagic-editor</th><th>GrapesJS</th><th>Appsmith</th><th>ToolJet</th></tr></thead><tbody><tr><td>形态</td><td>Schema 驱动</td><td>表单领域模型</td><td>可视化编排引擎</td><td>页面搭建器</td><td>自由画布</td><td>平台型应用搭建</td><td>平台型应用搭建</td></tr><tr><td>产物</td><td>JSON 页面配置</td><td>字段树 + 响应式规则</td><td>节点树 + 物料协议</td><td>页面 Schema</td><td>HTML/CSS 结构</td><td>平台内应用 + 数据连接</td><td>平台内应用 + 数据连接</td></tr><tr><td>前端栈</td><td>React 18</td><td>React 18</td><td>React（跟随 demo）</td><td>Vue 3</td><td>原生 TS</td><td>自有前端</td><td>自有前端</td></tr><tr><td>设计器</td><td>有（amis-editor）</td><td>无，需自建</td><td>有，内核级</td><td>有，页面级</td><td>有，画布级</td><td>有</td><td>有</td></tr><tr><td>物料/组件扩展</td><td>自定义组件 + 渲染器</td><td>自定义字段</td><td>物料协议 + 资产包</td><td>组件注册 + 运行时</td><td>Block / Plugin</td><td>平台内组件</td><td>平台内组件</td></tr><tr><td>数据源</td><td>API + fetcher</td><td>无（表单模型）</td><td>数据源插件</td><td>数据源 + 事件</td><td>需自行接入</td><td>内置连接器</td><td>内置连接器</td></tr><tr><td>出码</td><td>有限</td><td>无</td><td>有（出码插件）</td><td>有限</td><td>HTML/CSS 导出</td><td>平台锁定</td><td>平台锁定</td></tr><tr><td>后端依赖</td><td>无</td><td>无</td><td>无</td><td>无</td><td>无</td><td>有</td><td>有</td></tr><tr><td>上手成本</td><td>低</td><td>中</td><td>高</td><td>中高</td><td>中</td><td>低（平台）</td><td>低（平台）</td></tr><tr><td>长期治理成本</td><td>低到中</td><td>中</td><td>高</td><td>中高</td><td>中高</td><td>受平台约束</td><td>受平台约束</td></tr><tr><td>最适合</td><td>中后台 CRUD</td><td>复杂表单</td><td>平台底座</td><td>运营页面</td><td>视觉自由页面</td><td>快速内部工具</td><td>快速内部工具</td></tr><tr><td>主要风险</td><td>复杂交互受限</td><td>页面层需自建</td><td>概念多、接入重</td><td>业务逻辑弱</td><td>工程约束弱</td><td>数据与部署绑定平台</td><td>同左</td></tr></tbody></table><h2 id="决策树" tabindex="-1">决策树 <a class="header-anchor" href="#决策树" aria-label="Permalink to &quot;决策树&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>需求进来</span></span>
<span class="line"><span>├─ 需要自带后端 / 数据库 / 账号体系？</span></span>
<span class="line"><span>│  ├─ 是 → Appsmith / ToolJet（平台型，接受平台锁定）</span></span>
<span class="line"><span>│  └─ 否 → 继续</span></span>
<span class="line"><span>├─ 页面主体是表单，且联动/校验复杂？</span></span>
<span class="line"><span>│  ├─ 是 → Formily（页面外壳可配 amis）</span></span>
<span class="line"><span>│  └─ 否 → 继续</span></span>
<span class="line"><span>├─ 需要非开发者长期拖拽搭建？</span></span>
<span class="line"><span>│  ├─ 是 → 继续</span></span>
<span class="line"><span>│  │  ├─ 要平台底座、物料治理、出码 → lowcode-engine</span></span>
<span class="line"><span>│  │  └─ 要运营页面、数据源、动画 → tmagic-editor</span></span>
<span class="line"><span>│  └─ 否 → 继续</span></span>
<span class="line"><span>├─ 需要像素级自由布局 / 导出 HTML/CSS？</span></span>
<span class="line"><span>│  ├─ 是 → GrapesJS（自建工程约束）</span></span>
<span class="line"><span>│  └─ 否 → amis（Schema 驱动，最快落地）</span></span></code></pre></div><p>决策树只能排除明显不合适的选项。最终选择还要过三道验证：最小 demo 能否跑通、扩展点能否满足、产物能否进入现有发布流程。</p><h2 id="同一需求-五种方案" tabindex="-1">同一需求，五种方案 <a class="header-anchor" href="#同一需求-五种方案" aria-label="Permalink to &quot;同一需求，五种方案&quot;">​</a></h2><p>需求：一个「客户运营后台」，含概览卡片、客户列表 CRUD、复杂表单（联动 + 异步校验）、状态筛选、导出。</p><table tabindex="0"><thead><tr><th>方案</th><th>实现方式</th><th>优点</th><th>代价</th></tr></thead><tbody><tr><td>amis 单栈</td><td>全部页面用 amis Schema</td><td>最快，列表/表单/弹窗都现成</td><td>复杂联动要写自定义组件，模型能力弱</td></tr><tr><td>Formily 单栈</td><td>自建页面壳，表单与列表都用 Formily</td><td>表单能力强，字段模型清晰</td><td>列表、弹窗、布局要自己写</td></tr><tr><td>lowcode-engine</td><td>搭一套设计器 + 物料，业务方自己编</td><td>长期可扩展，产物是节点树</td><td>接入成本高，需要物料治理与出码链路</td></tr><tr><td>tmagic-editor</td><td>用页面搭建器做运营页，数据源接接口</td><td>页面生产快，支持事件与动画</td><td>复杂表单与 CRUD 不是强项</td></tr><tr><td>GrapesJS</td><td>自由画布拖拽，导出 HTML/CSS</td><td>视觉自由，产物可脱离框架</td><td>数据、校验、权限都要自建</td></tr></tbody></table><p>本教程第 15 章的综合实战选择「amis 负责页面与 CRUD + Formily 负责复杂表单」，理由是同工程组合、无跨 iframe、复杂度可控。选择 lowcode-engine 或 tmagic-editor 也能完成，但它们的设计器能力在这个需求里利用率不高，引入成本大于收益。</p><h2 id="对照-不复制" tabindex="-1">对照，不复制 <a class="header-anchor" href="#对照-不复制" aria-label="Permalink to &quot;对照，不复制&quot;">​</a></h2><p>第 16~20 章的 mini-lowcode 会实现 Schema、渲染器、设计器、历史与出码。每一章都会和商业产品做「同层对照」：</p><ul><li>Schema 协议对照 lowcode-engine 的节点协议与 tmagic-editor 的页面 Schema；</li><li>渲染器对照 lowcode-engine 的渲染器与 tmagic-editor 的 runtime；</li><li>设计器对照各产品的画布、大纲树、Setter 面板；</li><li>历史与插件对照 lowcode-engine 的命令栈与插件扩展点；</li><li>出码对照 lowcode-engine 的出码插件与 GrapesJS 的 HTML/CSS 导出。</li></ul><p>对照的目的是理解链路，不是复刻实现。mini-lowcode 是教学级系统，不宣称生产可用。</p><h2 id="选型落地检查表" tabindex="-1">选型落地检查表 <a class="header-anchor" href="#选型落地检查表" aria-label="Permalink to &quot;选型落地检查表&quot;">​</a></h2><ol><li><strong>产物能否被现有系统消费？</strong> 是 JSON、节点树还是 HTML？能否 diff、回滚、灰度？</li><li><strong>扩展点是否够用？</strong> 自定义组件、字段、插件、数据源，至少验证一个真实需求。</li><li><strong>版本是否可控？</strong> 核心包能否锁定精确版本，升级是否有迁移说明？</li><li><strong>团队能否维护？</strong> 出问题时能否定位到 Schema、物料、渲染器还是业务代码？</li><li><strong>退出成本是多少？</strong> 如果产品停止维护，产物能否迁移，业务能否继续运行？</li></ol><p>五个问题里，只要有一个答案含糊，就先做最小验证，不要直接进入全面推广。</p>`,18)])])}const g=d(s,[["render",i]]);export{m as __pageData,g as default};
